      },
      "技术水平": {
        "值": [ 0, "范围 [0, 10]，在'事后'阶段对技术水平进行数字评分。" ],
        "评语": [ "", "在'事后'阶段，用一段文字来评价技术水平。" ]
      }
    }
  },
  "风俗娘": {
    "爱尔玛": { "好感度": [ 10, "爱尔玛的好感度。傲娇角色，需要通过征服感和真心赞美来提升。" ] },
    "艾多莉": { "好感度": [ 25, "艾多莉的好感度。元气角色，共同体验飞翔的快乐会让她很开心。" ] },
    "咪咪": { "好感度": [ 20, "咪咪的好感度。活泼角色，陪她玩耍、给她新奇的玩具可以提升。" ] },
    "凯露露": { "好感度": [ 15, "凯露露的好感度。傲娇角色，需要耐心攻略和理解她的口是心非。" ] },
    "梦可": { "好感度": [ 30, "梦可的好感度。治愈系角色，安静的陪伴和温柔的抚摸能提升好感。" ] },
    "奥克芭": { "好感度": [20, "奥克芭的好感度。快感沉溺型角色，能承受住她失控的服务可以提升。"] },
    "爱洛耶": { "好感度": [ 0, "爱洛耶的好感度。专业务实的店长，认可你的能力或展现出对妖精族的理解可以提升。" ] },
    "普布拉拉": { "好感度": [ 25, "普布拉拉的好感度。温柔害羞的角色，温柔的对待和真诚的赞美能让她敞开心扉。" ] },
    "米尔琪": { "好感度": [ 15, "米尔琪的好感度。温顺被动的角色，温柔对待和享受她的服务能提升好感。" ] },
    "吉妮": { "好感度": [ 30, "吉妮的好感度。开朗治愈的角色，积极的互动和赞美会让她很开心。" ] },
    "毕儿提亚": { "好感度": [ 15, "毕儿提亚的好感度。反差新人，看似纯真却有虐待狂倾向，能承受她的反差可以提升。" ] },
    "莱咪": { "好感度": [ 20, "莱咪的好感度。技巧型角色，大胆探索并赞美她身体的各种可能性，会让她很开心。" ] },
    "艾莎": { "好感度": [ 18, "艾莎的好感度。御姐型角色，欣赏她的帅气，并在她展现温柔时给予回应可以提升。" ] }
  }
}

